ControlPropertyState.AutoRuleBindingString:
// [Ticket #10107] Rejected 보고서 라인 삭제
UpdateContext({
    locShowDeleteLineDialog: false,
    locDeletingLine: true,
    locDeleteLineError: Blank(),
    locReportNo: varSelectedReport.'Expense report number'
});

// 1. 동시성 방어: 삭제 직전 보고서 최신 상태 재조회 (DBNull 대비 IfError + Coalesce)
Set(
    varSelectedReport,
    Coalesce(
        IfError(LookUp('DCSL Expense Moblie Report (mserp)', 'Expense report number' = locReportNo), Blank()),
        varSelectedReport
    )
);

// 2. 삭제 대상 라인 최신 레코드 재조회
UpdateContext({
    locTargetLine: IfError(
        LookUp(
            'DCSL Expense Line Expense Moblie Entity (mserp)',
            'Expense transaction number (mserp_exptransnumber)' = locDeleteTransNo
        ),
        Blank()
    )
});

// 3. 검증 후 삭제
If(
    varSelectedReport.'Document Status' <> 'Document Status (mserp)'.Rejected,
    Notify("This report is no longer in Rejected status. Lines can only be deleted from a rejected report.", NotificationType.Warning, gblParams.notificationTime),

    IsBlank(locTargetLine),
    Notify("This expense line could not be found. It may have already been deleted.", NotificationType.Warning, gblParams.notificationTime),

    CountRows(colAttachedExpensesForReport) <= 1,
    Notify("The last expense line cannot be deleted. To cancel the whole report, withdraw it and delete the report from the Draft list.", NotificationType.Warning, gblParams.notificationTime),

    IfError(
        Remove('DCSL Expense Line Expense Moblie Entity (mserp)', locTargetLine),
        UpdateContext({
            locDeleteLineError: Coalesce(
                Substitute(
                    Match(FirstError.Details.HttpResponse, """message"":""([^""]*)""").FullMatch,
                    """message"":", ""
                ),
                FirstError.Message
            )
        })
    );
    If(
        IsBlank(locDeleteLineError),
        Notify("The expense line has been deleted.", NotificationType.Success, gblParams.notificationTime),
        Notify(Substitute(locDeleteLineError, """", ""), NotificationType.Error, gblParams.notificationTime)
    )
);

// 4. 화면 데이터 최신화 (성공/실패와 무관하게 실행)
Refresh('DCSL Expense Line Expense Moblie Entity (mserp)');
ClearCollect(
    colAttachedExpensesForReport,
    Filter(
        'DCSL Expense Line Expense Moblie Entity (mserp)',
        'Expense report number (mserp_expnumber)' = locReportNo &&
        'Expense line type' <> 'Expense line type (mserp)'.'Itemized line'
    )
);
ClearCollect(colAttachedExpenses, colAttachedExpensesForReport);
Set(
    varSelectedReport,
    Coalesce(
        IfError(LookUp('DCSL Expense Moblie Report (mserp)', 'Expense report number' = locReportNo), Blank()),
        varSelectedReport
    )
);
Set(varSelectedReportStatusItem, varSelectedReport.'Document Status');
UpdateContext({locDeletingLine: false, locDeleteTransNo: Blank(), locTargetLine: Blank()})
